    "cde.category_document": "Hujjat",
    "cde.linked_from_documents": "Hujjatlardan bogʻlangan",
    "cde.promote_failed": "Konteynerni ilgari surib boʻlmadi",
    "cde.promote_failed_generic": "Holat oʻtishi yakunlanmadi.",
    "cde.promote_insufficient_role": "Sizning rolingiz bu konteynerni keyingi holatga ilgari surolmaydi. Loyiha menejeri yoki admin talab qilinadi.",
    "cde.stat_total": "Jami konteynerlar",
